/** Independent priority frontier, all120 ordered full prefix trees, and controlled
 * execution of the source's finite clause candidates. Never eval question code. */
import assert from "node:assert/strict";
type Node={id:number;weight:number;leaves:Map<number,string>};
export function legacy2019Pm8PriorityOracle(freq:readonly number[]){const pending:Node[]=freq.map((weight,id)=>({id,weight,leaves:new Map([[id,""]])}));let next=4;const trace:number[][]=[];while(pending.length>1){const take=()=>{let best=0;for(let i=1;i<pending.length;i++)if(pending[i].weight<pending[best].weight||pending[i].weight===pending[best].weight&&pending[i].id<pending[best].id)best=i;return pending.splice(best,1)[0];},a=take(),b=take();trace.push([a.id,b.id,next]);pending.push({id:next++,weight:a.weight+b.weight,leaves:new Map([...a.leaves].map(([i,c])=>[i,"0"+c]as[number,string]).concat([...b.leaves].map(([i,c])=>[i,"1"+c]as[number,string])))});}const codes=[0,1,2,3].map(i=>pending[0].leaves.get(i)!);return{codes,cost:freq.reduce((n,f,i)=>n+f*codes[i].length,0),trace};}
function shapes(n:number):string[][]{if(n===1)return[[""]];const result:string[][]=[];for(let l=1;l<n;l++)for(const a of shapes(l))for(const b of shapes(n-l))result.push([...a.map(s=>"0"+s),...b.map(s=>"1"+s)]);return result;}
function permutations<T>(a:T[]):T[][]{if(!a.length)return[[]];return a.flatMap((x,i)=>permutations(a.filter((_,j)=>j!==i)).map(p=>[x,...p]));}
export function legacy2019Pm8ExhaustiveCost(freq:readonly number[]){const candidates=shapes(4).flatMap(s=>permutations(s));assert.equal(candidates.length,120);return Math.min(...candidates.map(c=>freq.reduce((n,f,i)=>n+f*c[i].length,0)));}
export function legacy2019Pm8Decode(bits:string,codes:readonly string[]){for(let i=0;i<4;i++)for(let j=0;j<4;j++)if(i!==j&&codes[j].startsWith(codes[i]))throw Error("NOT_PREFIX_FREE");let word="",text="";for(const bit of bits){word+=bit;const at=codes.indexOf(word);if(at>=0){text+="ABCD"[at];word="";}}assert.equal(word,"");return text;}
/** Predicates correspond to the seven source c/d alternatives, independent of
 * production helper bodies. `i` is read only after the source assigns it. */
export function legacy2019Pm8Program1Oracle(input:readonly number[],c:number,d:number){
 const parent=Array(12).fill(-1)as number[],left=[...parent],right=[...parent],freq=[...input,...Array(8).fill(-1)],node:number[]=[];let size=4,nsize=0,i:number|undefined,j:number|undefined,merges=0;
 const predicate=(which:number,at:number|undefined)=>{if((which===3||which===4)&&at===undefined)throw Error("UNASSIGNED_I");return[()=>nsize>=0,()=>nsize>=1,()=>nsize>=2,()=>parent[at!]<0,()=>parent[at!]>0,()=>size<=nsize,()=>size>=nsize][which]();};
 const sortNode=()=>{nsize=0;for(let at=0;at<size;at++)if(predicate(d,at))node[nsize++]=at;const ordered=node.slice(0,nsize).map((id,order)=>({id,order}));ordered.sort((a,b)=>freq[a.id]-freq[b.id]||a.order-b.order);ordered.forEach((v,k)=>node[k]=v.id);};
 try{sortNode();while(predicate(c,i)){if(merges>=3)throw Error("EXTRA_MERGE_AFTER_SINGLE_ROOT");i=node[0];j=node[1];if(i===undefined||j===undefined||i===j)throw Error("NO_TWO_CANDIDATES");left[size]=i;right[size]=j;freq[size]=freq[i]+freq[j];parent[i]=parent[j]=size;size++;merges++;sortNode();}if(size!==7||nsize!==1||parent.slice(0,size).filter(n=>n<0).length!==1)throw Error("INCOMPLETE_TREE");return{status:"tree"as const,parent:parent.slice(0,7),left:left.slice(0,7),right:right.slice(0,7),freq:freq.slice(0,7)};}catch(error){return{status:"invalid"as const,reason:(error as Error).message};}
}
export function legacy2019Pm8Program2Oracle(parent:readonly number[],left:readonly number[],e:number,f:number){
 const read=(a:readonly number[],k:number)=>{if(k<0||k>=a.length||!Number.isInteger(k))throw Error("INVALID_INDEX");return a[k];},outputs:string[]=[];
 try{for(let leaf=0;leaf<4;leaf++){let out="";const run=(k:number,depth:number)=>{if(depth>8)throw Error("NON_TERMINATING_RECURSION");const condition=[()=>k>=0,()=>read(left,k)===-1,()=>read(left,k)>=0,()=>read(parent,k)===-1,()=>read(parent,k)>=0][e]();if(!condition)return;run(read(parent,k),depth+1);const isLeft=[()=>read(left,k)===k,()=>read(left,read(parent,k))===k,()=>read(parent,k)===k,()=>read(parent,read(left,k))===k][f]();out+=isLeft?"0":"1";};run(leaf,0);outputs.push(out);}return{status:"codes"as const,codes:outputs};}catch(error){return{status:"invalid"as const,reason:(error as Error).message};}
}
